package uk.me.cormack.lighting7.fixture.property

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import java.awt.Color
import kotlin.math.abs
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertTrue

/**
 * The colour-temperature model behind a warm/cold white head's colour. The first two tests are the
 * load-bearing pins: `src/test/resources/fixture/whiteMix.fixture.json` is generated by an
 * independent port of the model, and `frontend/src/lib/whiteMix.test.ts` holds the client to the
 * same file, so the warmth control and the desk write one mix.
 */
class WhiteMixTest {

    @Serializable
    private data class Vector(val blackBody: List<BlackBody>, val pairs: List<Pair>)

    @Serializable
    private data class BlackBody(val kelvin: Int, val rgb: List<Double>)

    @Serializable
    private data class Pair(
        val warmKelvin: Int,
        val coldKelvin: Int,
        val levelsFor: List<LevelsFor>,
        val colourOf: List<ColourOf>,
    )

    @Serializable
    private data class LevelsFor(val colour: List<Int>, val levels: List<Int>)

    @Serializable
    private data class ColourOf(val levels: List<Int>, val colour: List<Int>, val kelvin: Int?)

    private val vector: Vector = lenient.decodeFromString(
        checkNotNull(javaClass.getResource("/fixture/whiteMix.fixture.json")) { "the shared vector is missing" }.readText(),
    )

    private companion object {
        val lenient = Json { ignoreUnknownKeys = true }
    }

    @Test
    fun `the black body matches the shared vector`() {
        for (entry in vector.blackBody) {
            val rgb = WhiteMix.kelvinToLinearRgb(entry.kelvin.toDouble())
            for (i in 0..2) {
                assertTrue(abs(rgb[i] - entry.rgb[i]) < 1e-5, "${entry.kelvin} K channel $i: ${rgb[i]} vs ${entry.rgb[i]}")
            }
        }
    }

    @Test
    fun `levels, colours and labels match the shared vector`() {
        for (pair in vector.pairs) {
            val mix = WhiteMix(pair.warmKelvin, pair.coldKelvin)
            for (case in pair.levelsFor) {
                val (r, g, b) = case.colour
                val levels = mix.levelsFor(Color(r, g, b))
                assertEquals(case.levels, listOf(levels.warm.toInt(), levels.cold.toInt()), "${pair.warmKelvin}/${pair.coldKelvin} ${case.colour}")
            }
            for (case in pair.colourOf) {
                val (warm, cold) = case.levels.map { it.toUByte() }
                val colour = mix.colourOf(warm, cold)
                assertEquals(case.colour, listOf(colour.red, colour.green, colour.blue), "${pair.warmKelvin}/${pair.coldKelvin} ${case.levels}")
                assertEquals(case.kelvin, mix.kelvinOf(WhiteMix.Levels(warm, cold)), "label of ${case.levels}")
            }
        }
    }

    @Test
    fun `every mix reads back as a colour that lands on the same mix, within two steps`() {
        // The colour is rounded to bytes on the way out, which moves its chromaticity a little.
        val mix = WhiteMix(3000, 6500)
        for (warm in 0..255) {
            for (cold in 0..255) {
                val colour = mix.colourOf(warm.toUByte(), cold.toUByte())
                val back = mix.levelsFor(colour)
                assertTrue(abs(back.warm.toInt() - warm) <= 2 && abs(back.cold.toInt() - cold) <= 2, "$warm/$cold came back ${back.warm}/${back.cold}")
            }
        }
    }

    @Test
    fun `a saturated colour lands on the end nearer its hue, at its own level`() {
        val mix = WhiteMix(3000, 6500)
        assertEquals(WhiteMix.Levels(255u, 0u), mix.levelsFor(Color.RED))
        assertEquals(WhiteMix.Levels(0u, 255u), mix.levelsFor(Color.BLUE))
        assertEquals(WhiteMix.Levels(128u, 0u), mix.levelsFor(Color(128, 0, 0)))
        assertEquals(WhiteMix.Levels(0u, 0u), mix.levelsFor(Color.BLACK))
    }

    @Test
    fun `the whites must be declared warm first`() {
        assertFailsWith<IllegalArgumentException> { WhiteMix(6500, 3000) }
    }
}
